1. What is the output of the following code?
class A { public void greet() { System.out.println("Hello from A"); } }
class B extends A { @Override public void greet() { System.out.println("Hello from B"); } }
class C extends B { }
public class Test {
    public static void main(String[] args) {
        A obj = new C();
        obj.greet();
    }
}

2. Will the following code compile? What is the output?
class Parent {
    public void display() { System.out.println("Parent"); }
}
class Child extends Parent {
    @Override
    protected void display() { System.out.println("Child"); }
}

3. Find the bug in this code:
class Animal {
    public void makeSound() { System.out.println("Generic sound"); }
}
class Dog extends Animal {
    public void MakeSound() { System.out.println("Woof"); }
}
public class Test {
    public static void main(String[] args) {
        Animal a = new Dog();
        a.makeSound();
    }
}

4. What is the output?
class Base {
    public Base getInstance() { System.out.print("Base "); return this; }
}
class Derived extends Base {
    @Override
    public Derived getInstance() { System.out.print("Derived "); return this; }
}
public class Test {
    public static void main(String[] args) {
        Base b = new Derived();
        b.getInstance();
    }
}

