6. What is the output? Why?
class Parent {
    public static void print() { System.out.println("Parent static"); }
    public void show() { System.out.println("Parent show"); }
}
class Child extends Parent {
    public static void print() { System.out.println("Child static"); }
    @Override
    public void show() { System.out.println("Child show"); }
}
public class Test {
    public static void main(String[] args) {
        Parent p = new Child();
        p.print();
        p.show();
    }
}

7. Identify the problem with this code and fix it:
class Animal {
    private String name;
    public Animal(String name) { this.name = name; logCreation(); }
    public void logCreation() { System.out.println("Animal created: " + name); }
}
class Dog extends Animal {
    private String breed;
    public Dog(String name, String breed) { super(name); this.breed = breed; }
    @Override
    public void logCreation() { System.out.println("Dog created: breed=" + breed); }
}

8. Refactor this code using method overriding to eliminate the instanceof checks:
void processAnimal(Object animal) {
    if (animal instanceof Dog) { ((Dog) animal).fetchBall(); }
    else if (animal instanceof Cat) { ((Cat) animal).purr(); }
    else if (animal instanceof Bird) { ((Bird) animal).sing(); }
}
